import React from 'react';

interface GrainIconProps {
  type: string;
  className?: string;
  strokeWidth?: number | string;
}

/**
 * Normaliza el strokeWidth para viewBox 0 0 100 100.
 * Si recibe valores típicos de iconos de 24x24 (1.4 a 2.5), los escala proporcionalmente a ~5.
 */
function resolveStrokeWidth(sw?: number | string): number {
  if (typeof sw === 'number') {
    if (sw <= 3) return sw * 2.8;
    return sw;
  }
  if (typeof sw === 'string') {
    const parsed = parseFloat(sw);
    if (!isNaN(parsed)) {
      if (parsed <= 3) return parsed * 2.8;
      return parsed;
    }
  }
  return 5.2;
}

